dashboard.definition:
{
  "title": "CDP Program Management",
  "description": "Projects, activities, ownership, and delivery status.",
  "inputs": {
    "input_workstream": {
      "type": "input.dropdown",
      "title": "Workstream",
      "dataSources": {
        "primary": "ds_workstreams"
      },
      "options": {
        "token": "workstream",
        "defaultValue": "__all__",
        "items": "> frame(label, value) | prepend(formattedStatics) | objects()"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "statics": [
          [
            "All workstreams"
          ],
          [
            "__all__"
          ]
        ],
        "formattedStatics": "> statics | formatByType(formattedConfig)",
        "label": "> primary | seriesByName('workstream') | renameSeries('label') | formatByType(formattedConfig)",
        "value": "> primary | seriesByName('workstream') | renameSeries('value') | formatByType(formattedConfig)"
      }
    },
    "input_status": {
      "type": "input.dropdown",
      "title": "Status",
      "options": {
        "token": "status",
        "defaultValue": "__all__",
        "items": [
          {
            "label": "All statuses",
            "value": "__all__"
          },
          {
            "label": "Planned",
            "value": "Planned"
          },
          {
            "label": "In progress",
            "value": "In progress"
          },
          {
            "label": "At risk",
            "value": "At risk"
          },
          {
            "label": "Blocked",
            "value": "Blocked"
          },
          {
            "label": "Complete",
            "value": "Complete"
          }
        ]
      }
    },
    "input_owner": {
      "type": "input.dropdown",
      "title": "Owner",
      "dataSources": {
        "primary": "ds_owners"
      },
      "options": {
        "token": "owner",
        "defaultValue": "__all__",
        "items": "> frame(label, value) | prepend(formattedStatics) | objects()"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "statics": [
          [
            "All owners"
          ],
          [
            "__all__"
          ]
        ],
        "formattedStatics": "> statics | formatByType(formattedConfig)",
        "label": "> primary | seriesByName('owner') | renameSeries('label') | formatByType(formattedConfig)",
        "value": "> primary | seriesByName('owner') | renameSeries('value') | formatByType(formattedConfig)"
      }
    }
  },
  "defaults": {
    "visualizations": {
      "global": {
        "showProgressBar": true,
        "showLastUpdated": false
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## CDP Program Management\nAuthor: G0TH3R · [Edit entries](/en-US/app/lookup_editor/lookup_edit?namespace=cdp_roadmap&lookup=cdp_roadmap.csv&type=csv&owner=nobody)"
      }
    },
    "viz_timeline": {
      "type": "splunk.timeline",
      "title": "Projects Scheulde",
      "dataSources": {
        "primary": "ds_timeline"
      },
      "options": {
        "x": "> primary | seriesByName('start_iso')",
        "y": "> primary | seriesByName('item')",
        "duration": "> primary | seriesByName('duration')",
        "category": "> primary | seriesByName('status')",
        "yAxisLabelWidth": 350,
        "additionalTooltipFields": [
          "owner",
          "workstream",
          "acceptance_criteria"
        ],
        "legendDisplay": "right",
        "resultLimit": 1000,
        "dataColors": "> primary | seriesByName('status') | matchValue(statusColors)"
      },
      "context": {
        "statusColors": [
          {
            "match": "Planned",
            "value": "#64748B"
          },
          {
            "match": "In progress",
            "value": "#0284C7"
          },
          {
            "match": "At risk",
            "value": "#D97706"
          },
          {
            "match": "Blocked",
            "value": "#DC2626"
          },
          {
            "match": "Complete",
            "value": "#16A34A"
          }
        ]
      }
    },
    "viz_details": {
      "type": "splunk.table",
      "title": "Entry register",
      "dataSources": {
        "primary": "ds_details"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "rowNumbers": false,
        "dataOverlayMode": "none"
      }
    },
    "viz_health": {
      "type": "splunk.table",
      "title": "Lookup health · all entries before filters",
      "dataSources": {
        "primary": "ds_health"
      },
      "options": {
        "count": 1,
        "wrap": true,
        "rowNumbers": false,
        "dataOverlayMode": "none"
      }
    },
    "viz_entries": {
      "type": "splunk.singlevalue",
      "title": "Entries",
      "dataSources": {
        "primary": "ds_summary"
      },
      "options": {
        "majorValue": "> primary | seriesByName('entries')"
      }
    },
    "viz_progress": {
      "type": "splunk.singlevalue",
      "title": "In progress",
      "dataSources": {
        "primary": "ds_summary"
      },
      "options": {
        "majorValue": "> primary | seriesByName('in_progress')"
      }
    },
    "viz_attention": {
      "type": "splunk.singlevalue",
      "title": "At risk / blocked",
      "dataSources": {
        "primary": "ds_summary"
      },
      "options": {
        "majorValue": "> primary | seriesByName('attention')"
      }
    },
    "viz_milestones": {
      "type": "splunk.singlevalue",
      "title": "Milestone points",
      "dataSources": {
        "primary": "ds_summary"
      },
      "options": {
        "majorValue": "> primary | seriesByName('milestones')"
      }
    }
  },
  "dataSources": {
    "ds_roadmap": {
      "type": "ds.search",
      "name": "Roadmap lookup — capped and validated",
      "options": {
        "query": "| inputlookup max=1001 cdp_roadmap.csv\n| eventstats count AS id_count BY id\n| eval start_epoch=strptime(start_date,\"%Y-%m-%d\"), end_epoch=strptime(end_date,\"%Y-%m-%d\")\n| eval validation=case(\n    len(trim(coalesce(id,\"\")))=0 OR len(trim(coalesce(workstream,\"\")))=0 OR len(trim(coalesce(milestone,\"\")))=0 OR len(trim(coalesce(owner,\"\")))=0, \"Missing required text\",\n    id_count>1, \"Duplicate ID\",\n    len(coalesce(start_date,\"\"))!=10 OR len(coalesce(end_date,\"\"))!=10 OR NOT match(coalesce(start_date,\"\"),\"^[0-9]{4}-[0-9]{2}-[0-9]{2}\") OR NOT match(coalesce(end_date,\"\"),\"^[0-9]{4}-[0-9]{2}-[0-9]{2}\"), \"Use YYYY-MM-DD dates\",\n    isnull(start_epoch) OR isnull(end_epoch) OR strftime(start_epoch,\"%Y-%m-%d\")!=start_date OR strftime(end_epoch,\"%Y-%m-%d\")!=end_date, \"Invalid date\",\n    end_epoch<start_epoch, \"End precedes start\",\n    NOT in(coalesce(status,\"\"),\"Planned\",\"In progress\",\"At risk\",\"Blocked\",\"Complete\"), \"Unsupported status\",\n    true(), \"OK\")\n| eval timeline_label=trim(coalesce(timeline_label,\"\")), duration=(end_epoch-start_epoch)*1000, item=id.\" | \".if(len(timeline_label)>0,timeline_label,milestone)\n| table id project workstream milestone timeline_label start_date end_date status owner dependency_ids acceptance_criteria start_epoch duration item validation",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_timeline": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_roadmap",
        "query": "where ($workstream|s$=\"__all__\" OR workstream=$workstream|s$) AND ($status|s$=\"__all__\" OR status=$status|s$) AND ($owner|s$=\"__all__\" OR owner=$owner|s$)\n| where validation=\"OK\"\n| sort 0 start_epoch id\n| head 1000\n| eval start_iso=strftime(start_epoch,\"%Y-%m-%dT%H:%M:%S\")\n| table start_iso item duration status owner workstream acceptance_criteria"
      }
    },
    "ds_details": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_roadmap",
        "query": "where ($workstream|s$=\"__all__\" OR workstream=$workstream|s$) AND ($status|s$=\"__all__\" OR status=$status|s$) AND ($owner|s$=\"__all__\" OR owner=$owner|s$)\n| sort 0 start_date id\n| head 1000\n| table id project workstream milestone timeline_label owner status start_date end_date dependency_ids acceptance_criteria validation"
      }
    },
    "ds_summary": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_roadmap",
        "query": "where ($workstream|s$=\"__all__\" OR workstream=$workstream|s$) AND ($status|s$=\"__all__\" OR status=$status|s$) AND ($owner|s$=\"__all__\" OR owner=$owner|s$)\n| stats count AS entries count(eval(status=\"In progress\")) AS in_progress count(eval(status=\"At risk\" OR status=\"Blocked\")) AS attention count(eval(duration=0 AND validation=\"OK\")) AS milestones"
      }
    },
    "ds_health": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_roadmap",
        "query": "stats count AS rows_read count(eval(validation!=\"OK\")) AS invalid_entries\n| eval health=if(invalid_entries>0,\"Invalid entries\",\"No validation errors\"), coverage=if(rows_read>1000,\"LIMIT EXCEEDED: only first 1,001 rows checked\",\"Within 1,000-entry limit\")\n| table rows_read invalid_entries health coverage"
      }
    },
    "ds_workstreams": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_roadmap",
        "query": "stats count BY workstream | where workstream!=\"__all__\" | sort 0 workstream | fields workstream"
      }
    },
    "ds_owners": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_roadmap",
        "query": "stats count BY owner | where owner!=\"__all__\" | sort 0 owner | fields owner"
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_workstream",
      "input_status",
      "input_owner"
    ],
    "layoutDefinitions": {
      "layout_overview": {
        "type": "absolute",
        "options": {
          "display": "auto-scale",
          "width": 1440,
          "height": 785
        },
        "structure": [
          {
            "item": "viz_header",
            "type": "block",
            "position": {
              "x": 16,
              "y": 8,
              "w": 1408,
              "h": 90
            }
          },
          {
            "item": "viz_entries",
            "type": "block",
            "position": {
              "x": 16,
              "y": 104,
              "w": 340,
              "h": 104
            }
          },
          {
            "item": "viz_progress",
            "type": "block",
            "position": {
              "x": 372,
              "y": 104,
              "w": 340,
              "h": 104
            }
          },
          {
            "item": "viz_attention",
            "type": "block",
            "position": {
              "x": 728,
              "y": 104,
              "w": 340,
              "h": 104
            }
          },
          {
            "item": "viz_milestones",
            "type": "block",
            "position": {
              "x": 1084,
              "y": 104,
              "w": 340,
              "h": 104
            }
          },
          {
            "item": "viz_details",
            "type": "block",
            "position": {
              "x": 16,
              "y": 222,
              "w": 1408,
              "h": 420
            }
          },
          {
            "item": "viz_health",
            "type": "block",
            "position": {
              "x": 16,
              "y": 656,
              "w": 1408,
              "h": 115
            }
          }
        ]
      },
      "layout_roadmap": {
        "type": "absolute",
        "options": {
          "display": "auto-scale",
          "width": 1440,
          "height": 600
        },
        "structure": [
          {
            "item": "viz_header",
            "type": "block",
            "position": {
              "x": 16,
              "y": 8,
              "w": 1408,
              "h": 90
            }
          },
          {
            "item": "viz_timeline",
            "type": "block",
            "position": {
              "x": 16,
              "y": 104,
              "w": 1408,
              "h": 480
            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Overview",
          "layoutId": "layout_overview"
        },
        {
          "label": "Roadmap",
          "layoutId": "layout_roadmap"
        }
      ]
    }
  }
}
